/*
 * sync_file_range Example: Demonstrates writing data and syncing only a specific 1KB range.
 */
#define _GNU_SOURCE
#define _FILE_OFFSET_BITS 64
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <errno.h>

#define FILE_NAME "test_range_sync.dat"
#define DATA_SIZE 4096 /* Ensure we write at least one full page (4KB) */
#define SYNC_OFFSET 2048
#define SYNC_LENGTH 1024

int main() {
    int fd;
    char buffer[DATA_SIZE];
    ssize_t written_bytes;
    int result;

    memset(buffer, 'A', DATA_SIZE);

    fd = open(FILE_NAME, O_CREAT | O_TRUNC | O_RDWR, 0644);
    if (fd == -1) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    written_bytes = write(fd, buffer, DATA_SIZE);
    if (written_bytes != DATA_SIZE) {
        perror("Error writing data");
        close(fd);
        return EXIT_FAILURE;
    }

    // Flush a specific range (SYNC_OFFSET for SYNC_LENGTH bytes) to disk.
    // We use WRITE to initiate the write-out and WAIT_AFTER to ensure completion.
    unsigned int flags = SYNC_FILE_RANGE_WRITE | SYNC_FILE_RANGE_WAIT_AFTER;

    result = sync_file_range(fd, SYNC_OFFSET, SYNC_LENGTH, flags);

    if (result == -1) {
        fprintf(stderr, "sync_file_range failed: %s\n", strerror(errno));
        // Note: EOPNOTSUPP often indicates the underlying filesystem doesn't support range sync
        // (e.g., NFS, older/non-standard filesystems).
    } else {
        printf("Successfully initiated and waited for sync of bytes %d to %d.\n", 
               SYNC_OFFSET, SYNC_OFFSET + SYNC_LENGTH);
    }

    close(fd);
    unlink(FILE_NAME); // Clean up
    return (result == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}
